import{_ as a,a as o,b as r,c as i}from"./chunks/142745305d98a416d152.M5Cpocz4.js";import{_ as l,C as s,o as n,c as h,j as e,a as c,E as m,a5 as d}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"最赚钱的细分领域就是你（如何打造你的细分领域）","description":"","frontmatter":{"title":"最赚钱的细分领域就是你（如何打造你的细分领域）","originalTitle":"The Most Profitable Niche Is You (How To Create Your Niche)","date":"2023-01-14","originalUrl":"https://thedankoe.com/letters/the-most-profitable-niche-is-you-how-to-create-your-niche/","minutes":10,"sourceHash":"c4c860e51a7dc8397f7525e2bc6c7c9062228da3ca541a7292ee02049fc9305d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-most-profitable-niche-is-you-how-to-create-your-niche/"}]]},"headers":[],"relativePath":"letters/the-most-profitable-niche-is-you-how-to-create-your-niche.md","filePath":"letters/the-most-profitable-niche-is-you-how-to-create-your-niche.md"}'),u={name:"letters/the-most-profitable-niche-is-you-how-to-create-your-niche.md"};function f(_,p,b,k,g,y){const t=s("ArticleMeta");return n(),h("div",null,[p[0]||(p[0]=e("h1",{id:"最赚钱的细分领域就是你-如何打造你的细分领域",tabindex:"-1"},[c("最赚钱的细分领域就是你（如何打造你的细分领域） "),e("a",{class:"header-anchor",href:"#最赚钱的细分领域就是你-如何打造你的细分领域","aria-label":'Permalink to "最赚钱的细分领域就是你（如何打造你的细分领域）"'},"​")],-1)),m(t),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/4pm5C3erORo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我买的第一门商业课程是一门教你打造六位数收入代运营机构的课。</p><p>那是六年前的事了。</p><p>在那之前，我看不到课程的价值。</p><p>我总是试着自己搞定一切。</p><p>我知道网上能搜到这些信息，确实也能，但它们从来没起过作用。</p><p>缺失的环节太多了。</p><p>社交媒体上的免费教育很棒，但算法鼓励人们将内容做短、做精，并只关注最有趣的话题。</p><p>每个人都只想要免费、免费、免费，这就导致了高价值建议被淹没在信息噪音的汪洋大海中。</p><p>别搞得好像你能免疫这套东西似的。没人能免疫。</p><p>当我受够了自己那一次又一次失败的创业尝试时，我准备好砸上我银行账户里的所有钱了。</p><p>我研究了那些最好的商业模式，找到了一个口碑不错的哥们儿，看了他的网络研讨会，然后付了 999 美元。</p><p>这在我的财务状况中可是<em>一大笔</em>钱。</p><p>这笔钱全刷在了我的第一张信用卡上。</p><p>而且，作为一个还在兼职打工的大学生，这给了我极大的压力。</p><p>我当时正同时应对着太多事情。</p><p>我根本不在乎的学业……但这推迟了我在找工作前必须让我的生意运转起来的最后期限。</p><p>一份显然毫无前途的兼职工作。</p><p>以及在此之前的多次创业失败。</p><p>当时真的是孤注一掷。</p><p>而且，长话短说，那次尝试没成。</p><p>课程很棒，教会了我文案、漏斗、销售的实用性，以及客户获取的流程，这些都为我未来的生意提供了动力……</p><p>但是，有三件事毁了我成功的机会：</p><ol><li>我特么压根就不在乎运营什么 Facebook 广告代运营机构。我根本就<em>不想</em>干这门生意。</li><li>给本地企业发陌生邮件既耗时又充满压力，而且他们都没钱付给我。</li><li>我从未对我的细分领域有过信心，这导致了巨大的内耗和闪光物体综合症（总是被新事物分心）。</li></ol><p>我这段搞 Facebook 广告的经历，比市面上任何其他生意、课程或观点教会我的都要多。</p><p>而且，即便它没有给我什么直接的教训，它也指出了我未来开展的所有生意中都会存在的一个问题。</p><p>选择细分领域。</p><p><em>在深入探讨之前，这是一篇预先安排好的内容（但我依然打算在这里提供尽可能多的价值）。</em></p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">第一期单人创业冲刺班（Solopreneur Sprint）将于 2 月 7 日开始</a>。我们首先要探讨的，正是如何打造一个你有信心的、像你自己的细分领域。欢迎去了解一下。</p><p>这是一个价值 150 美元的同期课程，有着有趣但极具影响力的结构（这样我就不用为了同样的资料向你收取几千美元了）。</p><h2 id="最赚钱的细分领域就是你" tabindex="-1">最赚钱的细分领域就是你 <a class="header-anchor" href="#最赚钱的细分领域就是你" aria-label="Permalink to &quot;最赚钱的细分领域就是你&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>广告代运营并不是我的第一次，也不是我最后一次创业尝试。</p><p>其他人已经跑通了自由职业模式，而我还不想就这么放弃（尽管我之前已经“放弃”过很多次了）。</p><p>在我苦干挣到了我的第一个六位数收入后，我偶然发现了 Twitter。</p><p>我在一个叫做“搞钱推特（Money Twitter）”的小圈子里发现了一些账号，他们向我展示了一条通向我今天所在位置的道路。</p><p>这一切并不是一蹴而就的，但我对我的品牌未来有了清晰的愿景。</p><p>我写内容，做产品，并专注于解决那些阻碍我实现理想未来的问题。</p><p>但是，有一件事让我在商业圈的众人中脱颖而出：</p><p><em>我没有一个静态不变的细分领域。</em></p><p>我重新定位的新服务是为创作者提供营销咨询（跳出本地企业这个细分领域才是明智之举），但我并不只谈论营销。</p><p>我想谈什么就谈什么，并且用一种能向广泛受众阐明该话题重要性的方式来谈论。</p><p>如果我想聊聊情绪管理，我就聊。</p><p>如果我想聊聊健身和营养，我就聊。</p><p>如果我想发一条振奋人心的建议，我就发。</p><p>我 80% 的内容<strong>都不</strong>围绕我的服务展开，但这无关紧要。</p><p>凭什么要围绕它？</p><p>如果我能同时对商业和健身感兴趣，其他人也能。</p><p>而且，如果你“理应”要缩小你的细分领域，这难道不是最好的方法吗？</p><p>直接把目标对准那些像你一样的人，或者那些因为与你有相似的理想未来而想成为你的人。</p><p>又不是让你在<strong>所有</strong>的内容里都去推销你的产品或服务。</p><p>而且，你可以建立一个系统，把建立权威的内容和用于推销的内容都融入进去。</p><p>如果我想推出一个新产品或服务，我会这么做：</p><ol><li>随心所欲地谈论我想谈的内容，用一种有趣且能带来增长的方式。</li><li>围绕产品或服务中的主题，制定一个为期 3 周的策略（这能建立权威，而且这也是我目前在<a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">单人创业冲刺班</a>上正在做的事……注意了——我在上一封信里谈到商业了吗？）。</li><li>为了建立客户认知，从入门级内容开始，随着发布日的临近，逐渐过渡到进阶内容。</li><li>自上而下地撰写长篇、中篇和短篇内容。这样一来，推销文案自然而然就写出来了。</li><li>把有效的方法系统化，并在一周内融入促销内容，以保持高销量。比如围绕你的服务，每两周发一次主题连帖（threads）。</li></ol><p>你的品牌和你的产品之间存在着微妙的分野。你的品牌<em>不是</em>你的产品。</p><p>几篇“跑题”的内容并不会毁掉你的收入。如果你清楚自己在做什么，它们实际上还能帮你赚钱。</p><p>我很幸运，在开始当创作者的时候，我就已经解决了我的财务问题。</p><p>大多数人是为了赚钱才开始的，这挺好，但生存的需要会毁掉你的创造性思维。</p><p>大多数创作者一开始都信奉某种商业意识形态，这种意识形态告诉他们要尽可能地垂直细分，把目标瞄准一个跟自己毫无共同点的人，然后用一项自己根本不关心的技能去获取结果。难怪人们放弃得那么快。</p><p>如果你想消除所有竞争，你的格局必须更大。</p><p>个人品牌<em>可以</em>成为获取客户的一种手段。</p><p>但是，当你把你想传达的信息视为你毕生的事业时，就不可能把所有东西都塞进一个传统的细分领域里。</p><p>你生活中的宏大目标将需要多种技能、兴趣和专业知识。就像灵性如何有助于实现财务自由，或者如何在商业中进行情绪管理一样。正是你的兴趣，让你的品牌独一无二。</p><h2 id="如何打造你的一人细分领域" tabindex="-1">如何打造你的一人细分领域 <a class="header-anchor" href="#如何打造你的一人细分领域" aria-label="Permalink to &quot;如何打造你的一人细分领域&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>从灵性的视角来看，你的“品牌”或“自我”，要么是机械重复商业意识形态的产物，要么是你有意识的个人创造。</p><p>如果你的品牌保持静止不变，你将会陷入痛苦的深渊。相反，我们需要进化，永不停歇。</p><p>因为如果你不进化，你就会被困在<a href="https://thedankoe.com/the-one-person-business-roadmap-99-of-creators-make-this-mistake/" target="_blank" rel="noreferrer">创作者发展的初级阶段。</a></p><p>让我们来看看如何（为了生意的目的）重塑你自己。</p><h3 id="_1-勾画你的理想未来" tabindex="-1">1) 勾画你的理想未来 <a class="header-anchor" href="#_1-勾画你的理想未来" aria-label="Permalink to &quot;1) 勾画你的理想未来&quot;">​</a></h3><p>你的故事将如何收尾？</p><p>结局会是内心的平静、健康的身体和充实的工作吗？还是你毫无头绪？</p><p>你的故事正是让你的个人品牌与众不同的地方。</p><p>如果你没有<a href="https://thedankoe.com/the-focus-formula-how-to-take-control-of-your-life/" target="_blank" rel="noreferrer">对未来的愿景</a>，你要如何在有利的方向上进行自我教育并付诸执行？</p><p>静下心来好好想想。</p><p>我们在第 3 步会再回到这个话题。</p><h3 id="_2-聪明的模仿" tabindex="-1">2) 聪明的模仿 <a class="header-anchor" href="#_2-聪明的模仿" aria-label="Permalink to &quot;2) 聪明的模仿&quot;">​</a></h3><blockquote><p>当你从一个作家那里拿东西时，那是剽窃，但<strong>当你从许多作家那里拿东西时，这就叫做研究</strong>。—— 威尔逊·米兹纳 (Wilson Mizner)</p></blockquote><p>我的表达声音，是我所热爱的各种声音的结合体。</p><p>我的品牌设计，是我随着时间的推移渐渐喜欢的颜色、感觉和风格的结合体。</p><p>我的产品、网站和落地页，都是汲取了其他人最棒的部分制作而成的。</p><p>这里学个配色，那里借个按钮，这边转个语气，以及其他的细微差别。</p><p>我说的不是那些让你看起来像个抄袭者的几个大动作。我说的是每一个极其微小的区别。这些细节会随着时间产生复利效应。</p><p>你通过汲取你渴望成为的人身上最棒的特质，并将其内化为你自己的东西，从而形成“你自己的做事方式”。</p><p>这适用于任何项目，但你具体需要这样做：</p><ul><li>写下对你影响最深的那些书</li><li>写下你最喜欢其风格的创作者、作者或公众人物</li><li>将自己沉浸在他们的作品中，训练你的大脑以那种风格去思考</li><li>写下他们的语气、声音，以及让他们脱颖而出的原因</li><li>研究他们的产品、落地页，以及他们如何赚钱的每一个细节</li></ul><p>简而言之，建立一个属于你的导师部落，并在一段较长的时间内只消费他们的内容。</p><p>成为他们最好的朋友（在精神上）。</p><p>然后，通过这种精神传递你对自己所做之事的激情。</p><p>如果你的潜意识能将他们的想法拼凑成一个属于你的原创想法，你就不需要去照抄他们。</p><p>你是一个装载各种视角的容器，<a href="https://thedankoe.com/how-to-copy-your-way-to-success-instead-of-mediocrity/" target="_blank" rel="noreferrer">而这正是让你独一无二的原因。</a></p><p>如果你养成习惯，去研究你渴望成为的人的方方面面，好的点子就会自然而然地涌现。</p><p>然后，从你自己的视角出发，去执行这些点子。</p><p>视角是以目标为导向的。</p><p>所以，从“努力将理想未来化为现实”的视角去进行创作。</p><p>有些人写日记，是因为他们的目标是头脑清晰。</p><p>有些人在网上写作，是因为他们的目标是财务自由。</p><p>你的目标是什么？特定的技能和兴趣又能如何帮你实现这个目标？</p><h3 id="_3-从写书到品牌内容" tabindex="-1">3) 从写书到品牌内容 <a class="header-anchor" href="#_3-从写书到品牌内容" aria-label="Permalink to &quot;3) 从写书到品牌内容&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>每一个故事都有一个理想的结局，一个终极目标。</p><p>通往这个终极目标的道路上，将布满高潮、低谷、情绪、战斗、错误，以及需要被系统化整理的解决方案。</p><p>以下是如何将你的“自我”或你的品牌，转变成一个容纳你的内容、产品和服务的细分领域：</p><ul><li>把你的理想未来当作这个故事的终极目标。</li><li>回顾你的过去，有那么几个关键时刻可以作为你这本书的起点。</li><li>写下这本书的大纲。为了达到最终目标，必须包含哪些章节？</li><li>为这些章节中的每一章列出要点。</li></ul><p>这不是一蹴而就的，但你需要一个大纲。</p><p>章节的灵感会在你体验生活、不断进步的过程中涌现出来。</p><p>你一开始可能会不知道某些章节该写什么，而这正是意义所在。</p><p>你必须获取技能、兴趣和专业知识，才能真正实现你想要的现实。</p><p>你就是那个吸引追随者的引路人。</p><p>追逐你的目标，解决阻挡在路上的问题，并把你学到的教训传承下去。</p><h3 id="_4-写下你的故事" tabindex="-1">4) 写下你的故事 <a class="header-anchor" href="#_4-写下你的故事" aria-label="Permalink to &quot;4) 写下你的故事&quot;">​</a></h3><p>故事成就了品牌，而你的故事是独一无二的。</p><p>你的故事让你能够与那些正在经历与你相同低谷的人产生共鸣。</p><p>这让人们看到了走出困境的希望，而你，就是指引他们的灯塔。</p><p>既然你已经有了人生故事的大纲，现在，开始写吧。</p><ul><li>将每一章的小节写成文章或新闻通讯。</li><li>将这些文字重新利用，做成播客或 YouTube 视频。</li><li>将要点浓缩成推特长文（thread）、轮播图或 LinkedIn 帖子。</li><li>将这些要点重写为引人入胜的推文。</li><li>将这些推文转化为短视频（reels）和其他平台的帖子。</li></ul><p>这个过程能让你对所谈论的主题产生多维度的理解。</p><p>而且，如果你还记得那些最好的学习方式，教学正是其中之一。</p><p>你会讨厌自己最初创作的内容，但这正是你发现要解决什么问题的方式。</p><p>如果在写作时你感到挣扎，这是一件好事。</p><h3 id="_5-遇到疑虑-拉大视角" tabindex="-1">5) 遇到疑虑，拉大视角 <a class="header-anchor" href="#_5-遇到疑虑-拉大视角" aria-label="Permalink to &quot;5) 遇到疑虑，拉大视角&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>解决挣扎的解药在于视角。</p><p>这段旅程很艰难。</p><p>你会很难清晰地表达你的细分领域（niche），因为没有人想把自己框死在盒子里。</p><p>要明白，你不需要立刻解决这个问题。</p><p>相反，你需要设定一个去解决这个问题的意图。</p><p>以此为起点，你通过课程、内容和对话来进行自我教育，这些会在你的大脑中储备创意的火力。</p><p>用各种潜在的解决方案让你的大脑超载。</p><p>只是别分心。</p><p>接下来，拉大视角。</p><p>给你的大脑一些喘息的空间，去构思解决那个问题的创造性方案。</p><p>去散散步。和朋友出去玩。去健身房。</p><p>做任何能让你停止思考工作的事情。</p><p>就像变魔术一样，“顿悟（aha!）”时刻会降临。</p><p>你的潜意识会将突破性的想法传递给你的显意识。</p><p>这个循环往复的过程被称为主权生活（sovereign living）。</p><p>生活的高潮与低谷，不会被工作的日常琐碎所掩盖。</p><p>记住这一点，享受你接下来的一天。</p><p><strong>– Dan Koe</strong></p><p>附言：第一期独立创业者冲刺营（Solopreneur Sprint）将于2月7日开始。</p><p>这是为不堪重负的创作者准备的为期14天的高强度策略：</p><ul><li>建立你一人企业的基础</li><li>打造专属你一人的细分领域并建立自信</li><li>撰写 20 多篇基础内容（你可以用 1000 种不同的方式重新利用它们）</li><li>学习零成本策略，让你的内容和个人主页获得曝光（从而吸引粉丝）</li><li>重新利用你最好的内容，并将它们作为杠杆以实现更快的增长</li></ul><p><em>而且没有普通训练营模式（cohort model）的高昂价格。</em></p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">如果你感兴趣，请在这里报名。</a></p><p>价格是 150 美元（为了一个你可以终生作为杠杆的品牌）。</p><hr><p><a href="/en/letters/the-most-profitable-niche-is-you-how-to-create-your-niche">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',148))])}const T=l(u,[["render",f]]);export{P as __pageData,T as default};
